package ai.codeandcraft.secondbrain;
import android.content.Context;import android.net.Uri;import android.system.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;import java.util.zip.*;import org.json.*;
/** A bounded local snapshot of verified evidence. Hashes are integrity checks, not a signature. */
public final class SourceBundle {
 private SourceBundle(){}
 static final long MAX_BYTES=512L*1024*1024;static final int MAX_ENTRIES=4096;
 private static void require(boolean b,String m)throws IOException{if(!b)throw new IOException(m);}
 /** Canonical lowercase UUIDs are the ownership key for derived private files. */
 static String meetingId(File meeting)throws IOException{require(meeting!=null,"Invalid meeting id");String id=meeting.getName();try{require(id.length()==36&&UUID.fromString(id).toString().equals(id)&&id.equals(meeting.getCanonicalFile().getName()),"Invalid meeting id");}catch(IllegalArgumentException error){throw new IOException("Invalid meeting id",error);}return id;}
 private static void cancelled(AtomicBoolean c)throws IOException{require(!Thread.currentThread().isInterrupted()&&(c==null||!c.get()),"Source bundle cancelled; original evidence retained");}
 static String sha(File f)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)d.update(b,0,n);}return hex(d.digest());}
 private static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format(Locale.ROOT,"%02x",v&255));return s.toString();}
 private static JSONObject read(File f,int max)throws Exception{require(f.isFile()&&f.length()<=max,"Missing or oversized bundle metadata");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=new FileInputStream(f)){byte[] b=new byte[8192];int n,total=0;while((n=in.read(b))!=-1){total+=n;require(total<=max,"Bundle metadata resource limit");out.write(b,0,n);}}return new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8));}
 private static File child(File root,String path)throws Exception{File f=new File(root,path).getAbsoluteFile();require(f.equals(f.getCanonicalFile())&&f.getPath().startsWith(root.getCanonicalPath()+File.separator),"Source bundle path or symbolic link rejected");return f;}
 private static void add(File root,String path,TreeMap<String,File> files)throws Exception{File f=child(root,path);require(f.isFile(),"Missing bundle source: "+path);require(files.put(path,f)==null,"Duplicate bundle path");}
 private static void jsonEvents(File root,String name,TreeMap<String,File> out)throws Exception{File dir=child(root,name);if(!dir.exists())return;require(dir.isDirectory(),"Invalid event directory");File[] entries=dir.listFiles();require(entries!=null&&entries.length<=256,"Event directory resource limit");for(File f:entries){require(!f.getName().endsWith(".part"),"Unfinished event; retry export after the save finishes");require(f.getName().matches("[a-f0-9-]{36}\\.json"),"Unexpected event file");add(root,name+"/"+f.getName(),out);}}
 private static TreeMap<String,File> sources(Context context,File root)throws Exception{
  require(root.getName().equals(root.getCanonicalFile().getName()),"Meeting identity changed by symbolic link");root=root.getCanonicalFile();
  require(!RecorderService.isRecording(),"Finish recording before exporting");require(UUID.fromString(root.getName()).toString().equals(root.getName()),"Invalid meeting id");require(root.getCanonicalPath().startsWith(context.getFilesDir().getCanonicalPath()+File.separator),"Meeting must remain in private local storage");
  JSONObject meta=read(child(root,"session.json"),262144);String status=meta.optString("status");require("COMPLETED".equals(status)||"RECOVERED_INTERRUPTED".equals(status),"Finish or recover the recording before exporting");JSONArray pending=meta.optJSONArray("pending");require(pending==null||pending.length()==0,"Unfinished audio chunks cannot be exported");
  TreeMap<String,File> out=new TreeMap<>();add(root,"session.json",out);JSONArray chunks=meta.getJSONArray("chunks");require(chunks.length()>0&&chunks.length()<=512,"Audio chunk resource limit");for(int i=0;i<chunks.length();i++){JSONObject c=chunks.getJSONObject(i);String name=c.getString("filename");LocalAudioReference.Source audio=ManualSpeakerCorrections.source(root,name);require(audio.durationMs==c.getLong("durationMillis"),"Saved audio duration mismatch");add(root,name,out);}
  File[] parts=root.listFiles((d,n)->n.endsWith(".wav.part"));require(parts!=null&&parts.length==0,"Recover unfinished audio before exporting");EvidenceNoteStore.load(root);ManualSpeakerCorrections.load(root);jsonEvents(root,"notes",out);jsonEvents(root,"corrections",out);
  File legacy=child(root,"transcripts");if(legacy.exists()){require(legacy.isDirectory(),"Invalid transcript directory");File[] records=legacy.listFiles();require(records!=null&&records.length<=128,"Legacy transcript resource limit");for(File record:records){require(record.isDirectory()&&record.getName().matches("[A-Za-z0-9_-]{1,80}"),"Invalid legacy transcript path");TranscriptTruthStore.load(child(root,"transcripts/"+record.getName()));add(root,"transcripts/"+record.getName()+"/record.json",out);add(root,"transcripts/"+record.getName()+"/source.wav",out);}}
  JSONArray briefs=MeetingBriefStore.load(context,root);jsonEvents(root,"briefs",out);
  TreeMap<String,JSONObject> jobs=new TreeMap<>();JSONObject job=WindowedTranscription.inspect(context,root);if(job!=null)jobs.put(job.getString("jobId"),job);
  for(int i=0;i<briefs.length();i++){JSONArray items=briefs.getJSONObject(i).getJSONArray("items");for(int j=0;j<items.length();j++){JSONArray citations=items.getJSONObject(j).getJSONArray("citations");for(int k=0;k<citations.length();k++){String id=citations.getJSONObject(k).getJSONObject("anchor").getString("jobId");if(!jobs.containsKey(id))jobs.put(id,WindowedTranscription.inspectJob(context,root,id));}}}
  for(JSONObject acceptedJob:jobs.values()){String prefix="transcription-jobs/"+acceptedJob.getString("jobId")+"/";add(root,prefix+"plan.json",out);JSONArray windows=acceptedJob.getJSONArray("windows");for(int i=0;i<windows.length();i++){JSONObject w=windows.getJSONObject(i);String truth=w.getString("truthDirectory");add(root,prefix+String.format(Locale.ROOT,"accepted-%04d.json",w.getJSONObject("window").getInt("index")),out);add(root,prefix+truth+"/record.json",out);add(root,prefix+truth+"/source.wav",out);}}
  return out;
 }
 public static JSONObject create(Context context,File root,AtomicBoolean cancel)throws Exception{return create(context,root,cancel,MAX_ENTRIES,MAX_BYTES);}
 static JSONObject create(Context context,File root,AtomicBoolean cancel,int maxEntries,long maxBytes)throws Exception{
  require(maxEntries>0&&maxEntries<=MAX_ENTRIES&&maxBytes>0&&maxBytes<=MAX_BYTES,"Invalid source bundle resource limits");cancelled(cancel);String meetingId=meetingId(root);TreeMap<String,File> files=sources(context,root);require(files.size()<=maxEntries,"Source bundle entry limit");JSONArray entries=new JSONArray();long total=0;Map<String,String> hashes=new TreeMap<>();for(Map.Entry<String,File> e:files.entrySet()){cancelled(cancel);long size=e.getValue().length();require(size>=0&&size<=maxBytes-total,"Source bundle byte limit");total+=size;String hash=sha(e.getValue());hashes.put(e.getKey(),hash);entries.put(new JSONObject().put("path",e.getKey()).put("bytes",size).put("sha256",hash));}
  File parent=new File(context.getFilesDir().getCanonicalFile(),"exports").getAbsoluteFile();require(parent.equals(parent.getCanonicalFile()),"Invalid export directory");if(!parent.exists())require(parent.mkdir(),"Unable to create export directory");File[] previous=parent.listFiles();require(previous!=null&&previous.length<16,"Local export limit reached; move earlier bundles before creating more");require(parent.getUsableSpace()>total+16L*1024*1024,"Not enough free storage for source bundle");String id=meetingId+"--"+UUID.randomUUID().toString();File part=new File(parent,id+".zip.part"),result=new File(parent,id+".zip");require(part.createNewFile(),"Unable to reserve source bundle");
  JSONObject manifest=new JSONObject().put("schemaVersion",1).put("meetingId",meetingId).put("createdUtc",System.currentTimeMillis()).put("coverage","Original completed audio, saved legacy transcripts, current verified accepted windows, user notes, validated derivative brief revisions and manual labels. Historical accepted jobs are included only when referenced by a brief. Unaccepted attempts and unreferenced other job versions are excluded.").put("claimsVerified",false).put("wordTimingsAvailable",false).put("hashPurpose","Integrity only; not a signature or verification of transcript/notes accuracy").put("files",entries);
  byte[] manifestBytes=manifest.toString().getBytes(StandardCharsets.UTF_8);require(manifestBytes.length<=1048576,"Bundle manifest resource limit");
  try{
   try(FileOutputStream stream=new FileOutputStream(part);ZipOutputStream zip=new ZipOutputStream(stream)){zip.setLevel(1);ZipEntry first=new ZipEntry("manifest.json");zip.putNextEntry(first);zip.write(manifestBytes);zip.closeEntry();for(Map.Entry<String,File> e:files.entrySet()){cancelled(cancel);zip.putNextEntry(new ZipEntry(e.getKey()));MessageDigest d=MessageDigest.getInstance("SHA-256");long count=0;try(InputStream in=new FileInputStream(e.getValue())){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){cancelled(cancel);count+=n;require(count<=maxBytes,"Source grew during export");zip.write(b,0,n);d.update(b,0,n);}}zip.closeEntry();require(hashes.get(e.getKey()).equals(hex(d.digest())),"Evidence changed while exporting");}zip.finish();zip.flush();stream.getFD().sync();}
   require(part.length()<=maxBytes+4L*1024*1024,"Compressed bundle resource limit");cancelled(cancel);TreeMap<String,File> after=sources(context,root);require(after.keySet().equals(files.keySet()),"Evidence set changed during export");for(String name:hashes.keySet()){cancelled(cancel);require(hashes.get(name).equals(sha(after.get(name))),"Evidence changed after copying");}require(!result.exists()&&part.renameTo(result),"Unable to commit source bundle");try{FileDescriptor fd=Os.open(parent.getPath(),OsConstants.O_RDONLY,0);try{Os.fsync(fd);}finally{Os.close(fd);}}catch(Exception error){throw new IOException("Bundle committed but directory sync failed; verify before retrying",error);}return new JSONObject().put("file",result.getAbsolutePath()).put("sha256",sha(result)).put("bytes",result.length()).put("entryCount",files.size()).put("manifest",manifest);
  }catch(Exception error){if(part.exists())part.delete();throw error;}
 }
 public static boolean localDocument(Uri uri){if(uri==null||!"content".equals(uri.getScheme()))return false;String a=uri.getAuthority();return "com.android.externalstorage.documents".equals(a)||"com.android.providers.downloads.documents".equals(a)||"com.android.providers.media.documents".equals(a);}
 public static void copyVerified(File bundle,String expected,OutputStream destination)throws Exception{require(bundle.isFile()&&bundle.length()<=MAX_BYTES+4L*1024*1024&&expected.equals(sha(bundle)),"Prepared bundle changed; prepare it again");MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(bundle)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){destination.write(b,0,n);digest.update(b,0,n);}}destination.flush();require(expected.equals(hex(digest.digest())),"Bundle changed during local save");}
}
